SELECT concat(rt.REQUIREMENT_TITLE_ID,' - ', rt.REQUIREMENT_TITLE) as REQUIREMENT_TITLE_NAME,rs.PARENT_REQUIREMENT_SET_UUID,concat(rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME) as REQUIREMENT_SET_UUID , r.REQUIREMENT_ID, IMPACTED_USER_STORY_ID, IMPACTED_USER_STORY_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, ius.REQUIREMENT_TITLE_UUID, USER_STORY_UUID,ius.ASSOCIATION_TYPE FROM IMPACTED_USER_STORY ius JOIN REQUIREMENT_TITLE rt ON ius.REQUIREMENT_TITLE_UUID = rt.REQUIREMENT_TITLE_UUID JOIN REQUIREMENT r ON rt.REQUIREMENT_TITLE_UUID = r.REQUIREMENT_ASSOCIATION_UUID AND ius.REQUIREMENT_UUID = r.REQUIREMENT_UUID left join REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID=r.REQUIREMENT_SET_UUID WHERE ius.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID AND ius.USER_STORY_UUID =:USER_STORY_UUID AND BINARY rt.REQUIREMENT_TITLE =:RequirementTitle and ASSOCIATION_TYPE IN ('REQUIREMENT','CONDITION_SATISFACTION') Union SELECT concat ( pr.PROCESS_ID, ' - ' , pr.PROCESS_NAME, ', ', pg.PAGE_ID , ' - ',pg.PAGE_NAME, ', ' ,rt.USER_ACTION_ID,' - ',rt.USER_ACTION_NAME) as REQUIREMENT_TITLE_NAME,rs.PARENT_REQUIREMENT_SET_UUID,concat(rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME) as REQUIREMENT_SET_UUID, r.REQUIREMENT_ID, IMPACTED_USER_STORY_ID, IMPACTED_USER_STORY_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, ius.REQUIREMENT_TITLE_UUID, USER_STORY_UUID,ius.ASSOCIATION_TYPE FROM IMPACTED_USER_STORY ius JOIN VIEW_USER_ACTION rt ON ius.USER_ACTION_UUID = rt.USER_ACTION_UUID JOIN REQUIREMENT r ON rt.USER_ACTION_UUID = r.REQUIREMENT_ASSOCIATION_UUID AND ius.REQUIREMENT_UUID = r.REQUIREMENT_UUID left join REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID=r.REQUIREMENT_SET_UUID JOIN PROCESS pr ON pr.PROCESS_UUID=rt.PROCESS_UUID JOIN PAGE pg ON pg.PAGE_UUID=rt.PAGE_UUID WHERE ius.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID AND USER_STORY_UUID =:USER_STORY_UUID AND BINARY concat (pr.PROCESS_NAME, ' - ',pg.PAGE_NAME, ' - ' ,rt.USER_ACTION_NAME) =:RequirementTitle and ASSOCIATION_TYPE IN ('USER_ACTION_REQUIREMENT','USER_ACTION_CONDITION_SATISFACTION') UNION SELECT concat(rt.REQUIREMENT_TITLE_ID,' - ', rt.REQUIREMENT_TITLE) as REQUIREMENT_TITLE_NAME, rs.PARENT_REQUIREMENT_SET_UUID,concat(rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME) as REQUIREMENT_SET_UUID,REQUIREMENT_ID, IMPACTED_USER_STORY_ID, IMPACTED_USER_STORY_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, ius.REQUIREMENT_TITLE_UUID, USER_STORY_UUID,ius.ASSOCIATION_TYPE FROM IMPACTED_USER_STORY ius JOIN REQUIREMENT_TITLE rt ON ius.REQUIREMENT_TITLE_UUID = rt.REQUIREMENT_TITLE_UUID JOIN REQUIREMENT r ON rt.REQUIREMENT_TITLE_UUID = r.REQUIREMENT_ASSOCIATION_UUID AND ius.REQUIREMENT_UUID = r.REQUIREMENT_UUID left join REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID=r.REQUIREMENT_SET_UUID WHERE ius.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID AND USER_STORY_UUID =:USER_STORY_UUID AND BINARY 'dummy' =:RequirementTitle and ASSOCIATION_TYPE IN ('REQUIREMENT','CONDITION_SATISFACTION') Union SELECT concat ( pr.PROCESS_ID, ' - ' , pr.PROCESS_NAME, ', ', pg.PAGE_ID , ' - ',pg.PAGE_NAME, ', ' ,rt.USER_ACTION_ID,' - ',rt.USER_ACTION_NAME) as REQUIREMENT_TITLE_NAME,rs.PARENT_REQUIREMENT_SET_UUID,concat(rs.REQUIREMENT_SET_ID, ' - ', rs.REQUIREMENT_SET_NAME) as REQUIREMENT_SET_UUID, r.REQUIREMENT_ID, IMPACTED_USER_STORY_ID, IMPACTED_USER_STORY_UUID, ius.REQUIREMENT_UUID, ius.CONDITION_SATISFACTION_UUID, ius.REQUIREMENT_TITLE_UUID, USER_STORY_UUID,ius.ASSOCIATION_TYPE FROM IMPACTED_USER_STORY ius JOIN VIEW_USER_ACTION rt ON ius.USER_ACTION_UUID = rt.USER_ACTION_UUID JOIN REQUIREMENT r ON rt.USER_ACTION_UUID = r.REQUIREMENT_ASSOCIATION_UUID AND ius.REQUIREMENT_UUID = r.REQUIREMENT_UUID left join REQUIREMENT_SET rs ON rs.REQUIREMENT_SET_UUID=r.REQUIREMENT_SET_UUID JOIN PROCESS pr ON pr.PROCESS_UUID=rt.PROCESS_UUID JOIN PAGE pg ON pg.PAGE_UUID=rt.PAGE_UUID WHERE ius.FUNCTIONAL_AREA_UUID =:APP_LOGGED_IN_FUNTIONAL_AREA_ID AND USER_STORY_UUID =:USER_STORY_UUID AND BINARY 'dummy' =:RequirementTitle and ASSOCIATION_TYPE IN ('USER_ACTION_REQUIREMENT','USER_ACTION_CONDITION_SATISFACTION') ORDER BY REQUIREMENT_ID DESC;